import{_ as e,o as t,c as s,ah as r}from"./chunks/framework.Yx0DUrwu.js";const u=JSON.parse('{"title":"Squidpy 教程","description":"","frontmatter":{},"headers":[],"relativePath":"tools/squidpy/index.md","filePath":"tools/squidpy/index.md","lastUpdated":1787828101000}'),n={name:"tools/squidpy/index.md"};function i(o,a,l,p,d,c){return t(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="squidpy-教程" tabindex="-1">Squidpy 教程 <a class="header-anchor" href="#squidpy-教程" aria-label="Permalink to &quot;Squidpy 教程&quot;">​</a></h1><p>Squidpy 是 scverse 生态中的空间组学分析工具，常用于 spatial transcriptomics 数据的空间邻域、图结构、共定位、空间自相关、ligand-receptor 和图像特征分析。它通常与 Scanpy/AnnData 配合使用：Scanpy 处理表达矩阵，Squidpy 处理 spatial coordinates, tissue images, and spatial graphs。</p><p>空间分析的关键不是把 UMAP 换成组织图片，而是把“细胞状态在哪里”和“哪些细胞彼此相邻”纳入解释。</p><div class="path-grid"><a href="/tools/squidpy/spatial-neighborhood"><strong>空间邻域与图分析</strong><span>构建 spatial graph，计算 neighborhood enrichment 和空间自相关。</span></a><a href="/biology/sequencing-principles"><strong>空间测序原理</strong><span>回到空间转录组平台差异，理解分辨率、捕获效率和坐标含义。</span></a><a href="/tools/anndata/"><strong>AnnData 空间字段</strong><span>理解 obsm[&quot;spatial&quot;], uns[&quot;spatial&quot;], and image metadata 如何保存。</span></a><a href="/references/"><strong>参考资料</strong><span>查看 Squidpy 官方教程和空间组学实践资料。</span></a></div><h2 id="适合回答的问题" tabindex="-1">适合回答的问题 <a class="header-anchor" href="#适合回答的问题" aria-label="Permalink to &quot;适合回答的问题&quot;">​</a></h2><div class="check-grid"><article><strong>哪些细胞类型相邻</strong><span>neighborhood enrichment 用于判断 cell type pairs 是否比随机情况更常相邻。</span></article><article><strong>哪些基因有空间模式</strong><span>Moran&#39;s I 等空间自相关指标可用于找 spatially variable genes。</span></article><article><strong>组织区域是否有结构</strong><span>把 histology image, spot coordinates, clusters, and expression 放在一起解释。</span></article><article><strong>细胞通讯是否有空间支持</strong><span>ligand-receptor 结果若有空间邻近证据，解释会更稳。</span></article></div><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><ul><li><a href="https://squidpy.readthedocs.io/" target="_blank" rel="noreferrer">Squidpy documentation</a></li><li><a href="https://squidpy.readthedocs.io/en/stable/notebooks/tutorials/index.html" target="_blank" rel="noreferrer">Squidpy tutorials</a></li><li><a href="https://scverse.org/" target="_blank" rel="noreferrer">scverse spatial ecosystem</a></li></ul>',8)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
